import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const PHARM_DISCLAIMER =
  'Educational pharmacology mechanisms only. Never use this platform for patient-specific dosing, prescribing, or clinical treatment decisions.';

const PHARM_DISCLOSURE = {
  status: 'conceptual_diagram_only' as const,
  summary:
    'Delivered with molecular receptor-pathway diagrams, ADME quantitative concepts, drug-class comparison matrices (MOA, indications, PK, ADRs, interactions, monitoring), and educational clinical examples linked to IUPHAR.',
};

function makePharmChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  classMeta: string,
  extraReadKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  mechanisms: string[],
  clinical: string,
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  return {
    id,
    domainId: 'pharmacology',
    chapterCode: `K${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['medical_foundations', 'clinical_applied', 'allied_health', 'graduate_research'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 3–4', unitOrModule: `Pharmacology & Therapeutics (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_uhs_mbbs', gradeOrYear: 'MBBS Professional II', unitOrModule: `General & Systemic Pharmacology (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'hms_pathways', gradeOrYear: 'MD Therapeutics Integration', unitOrModule: `Pharmacotherapy (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'qaa_biosciences', gradeOrYear: 'BS Hons / MPhil', unitOrModule: `Molecular Pharmacology (${chapterTitle})`, status: 'recommended' },
    ],
    prerequisites: ['Receptor physiology & autonomic transmission (E4, E5)', 'Enzyme kinetics & hepatic metabolism (F3, F18)'],
    learningObjectives: [
      `Specify exact molecular targets, mechanisms of action, and principal therapeutic indications in ${chapterTitle.toLowerCase()}.`,
      `Account for pharmacokinetic disposition, major contraindications, adverse effects, and CYP/P-gp drug interactions (${classMeta}).`,
      `Identify essential laboratory/clinical monitoring parameters and safety boundaries in educational vignettes.`,
    ],
    depthExplanations: {
      medical_foundations: `${mechanisms.join(' ')} Class summary (MOA / PK / Monitoring): ${classMeta}.`,
      clinical_applied: `Educational therapeutics & monitoring context for ${chapterTitle.toLowerCase()}: ${clinical} Safety notice: ${PHARM_DISCLAIMER}`,
      allied_health: `Medication administration safety, high-alert drug interactions, vital-sign/electrolyte checks, and adverse-reaction recognition in ${chapterTitle.toLowerCase()}: ${classMeta}`,
      graduate_research: `Quantitative receptor occupancy theory, biased agonism/allosteric modulation, CYP3A4/CYP2D6/UGT pharmacogenomics, and PK/PD modelling underlie ${chapterTitle.toLowerCase()}.`,
    },
    keyConcepts: [
      { term: 'Mechanism of Action & Target', definition: summary },
      { term: 'PK / Interactions / Monitoring', definition: classMeta },
      { term: 'Educational Clinical Example', definition: clinical },
    ],
    keyFacts: [
      `Class Disposition & Safety Profile: ${classMeta}.`,
      PHARM_DISCLAIMER,
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Potency determines maximum clinical efficacy of a drug.', correction: 'Potency (EC50) simply indicates the dose/concentration needed for half-maximal effect; Emax (maximal clinical efficacy) determines ceiling therapeutic benefit.' },
      { misconception: 'Generic bioequivalence means arbitrary active ingredients vary widely.', correction: 'Regulatory bioequivalence requires matching active drug, route, and 90% confidence intervals of AUC and Cmax (usually 80–125%), though narrow-therapeutic-index agents still warrant monitoring.' },
    ],
    clinicalCorrelation: clinical,
    summaryParagraph: `${chapterTitle} connects receptor transduction and pharmacokinetic ADME math to adverse-effect prevention, drug–drug interaction vigilance, and monitoring. Always strictly educational — never individualized prescribing.`,
    keyTakeaways: [
      mechanisms[0] ?? summary,
      classMeta,
      clinical,
    ],
    crossSubjectLinks: [
      { domainId: 'human_physiology', relation: 'Drugs amplify, block, or modulate intrinsic physiological receptors and ion channels.' },
      { domainId: 'pathology', relation: 'Pathologic organ insufficiency (renal CKD, hepatic cirrhosis) alters drug clearance and toxicity.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['2d_diagram', 'structured_text', 'clinical_case'],
    diagram: {
      id: `diag-k${num}`,
      title: `${chapterTitle} — Drug-Target → PD Effect → Monitoring Safety`,
      kind: 'pathway',
      caption: `${summary} (${classMeta})`,
      disclaimer: PHARM_DISCLAIMER,
      nodes: [
        { id: 'n1', label: 'Molecular Target & MOA', sublabel: mechanisms[0]?.slice(0, 62) || summary.slice(0, 62), tone: 'blue' },
        { id: 'n2', label: 'PK / Interaction Checkpoint', sublabel: classMeta.slice(0, 62), tone: 'amber' },
        { id: 'n3', label: 'Therapeutic vs ADR Monitoring', sublabel: clinical.slice(0, 62), tone: 'rose' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: 'Concentration–effect exposure' },
        { from: 'n2', to: 'n3', label: 'Clinical response & toxicity monitoring' },
      ],
    },
    assetDisclosure: PHARM_DISCLOSURE,
    activity: {
      title: `Mechanism, Interaction & Monitoring Audit (${chapterTitle})`,
      kind: 'case_reasoning',
      prompt: `For the drug classes in ${chapterTitle}, trace target receptor MOA, hepatic/renal clearance route, one high-risk contraindication/ADR, and key monitoring lab/vital sign (educational exercise only).`,
      keyTakeaway: clinical,
    },
    readingKeys: ['iuphar_pharmacology_edu', extraReadKey],
    shortAnswers: [
      { id: `sa-k${num}-1`, prompt: `State the MOA, primary indications, and ADME elimination route in ${chapterTitle}.`, expectedPoints: mechanisms.slice(0, 2), modelAnswer: `${mechanisms.join(' ')} (${classMeta}).`, level: 'medical_foundations' },
      { id: `sa-k${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} across MOA, ADRs, and contraindications.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'clinical_applied' },
      { id: `sa-k${num}-3`, prompt: `Specify major drug interactions and monitoring parameters for safety in ${chapterTitle.toLowerCase()}.`, expectedPoints: [classMeta, clinical], modelAnswer: `${classMeta}. ${clinical}`, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-k${num}-1`,
      title: `Educational Pharmacotherapy & Interaction Case: ${chapterTitle}`,
      scenario: `A non-prescribing teaching case reviews a patient experience involving ${summary.toLowerCase()} with concomitant renal/CYP factors (${classMeta}).`,
      questions: ['Which molecular receptor or transporter mediates the drug effect?', 'What toxicity or interaction demands close clinical monitoring?'],
      workedSolution: `${mechanisms[0]} Safety & monitoring focus: ${clinical}`,
      level: 'clinical_applied',
      disclaimer: PHARM_DISCLAIMER,
    },
    selfChecks: mcqs,
    educationalDisclaimer: PHARM_DISCLAIMER,
  };
}

